function Badge(name) {
  this.text = this.format(name);
}

Badge.prototype.format = function (name) {
  return "[" + name + "]";
};

function build(Ctor, ...args) {
  const obj = {};
  try {
    Ctor.apply(obj, args);
  } catch (error) {
    console.log(error.name);
  }
  Object.setPrototypeOf(obj, Ctor.prototype);
  return obj;
}

const badge = build(Badge, "Ada");
console.log(badge.text);
console.log(badge instanceof Badge);
console.log(typeof badge.format);
